6:  */
7: function rateLimit ({ limit = 60, windowMs = 60000, now = Date.now } = {}) {
8:   const clients = new Map()
9:   return function check (key) {
10:     const at = now()
11:     let entry = clients.get(key)
12:     if (!entry || at >= entry.resetAt) {
13:       entry = { count: 0, resetAt: at + windowMs }
14:       clients.set(key, entry)
15:     }
16:     entry.count += 1
17:     if (entry.count > limit) {
18:       return { allowed: false, retryAfterSec: Math.max(1, Math.ceil((entry.resetAt - at) / 1000)) }
19:     }
20:     return { allowed: true, remaining: limit - entry.count }
21:   }
22: }
23: 
24: module.exports = { rateLimit }
