            color: var(--text-secondary);
            font-size: 1.125rem;
        }

        .cards-wrapper {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
            align-items: stretch;
        }

        .card {
            background: var(--card-bg);
            border-radius: var(--radius);
            padding: 32px;
